from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 4.1 Structure of an atom · 8Cm.01–8Cm.03, 8TWSm.03
# =====================================================================================================
READ["4.1"] = L(
    H("Uncuttable?",
      "About 2400 years ago Greek thinkers named the smallest pieces of matter 'atomos', meaning 'cannot be cut'.",
      "Were they right? Is there anything smaller than an atom? Make a guess, then read on."),
    I("Atoms: the building blocks",
      "Every element is made of one type of atom. Atoms of different elements have different sizes and masses.",
      then=["Just as a few kinds of toy brick can build houses, cars and cities, about 90 natural kinds of atom build everything in the Universe."]),
    I("Inside an atom",
      "An atom is mostly **empty space**. It contains three kinds of particle.",
      fig={"kind": "atom", "shells": [2, 4], "p": 6, "n": 6, "title": "carbon atom"},
      table=[["Particle", "Where", "Charge", "Relative mass"],
             ["**proton**", "in the nucleus", "positive (+1)", "1"], ["**neutron**", "in the nucleus", "none (0)", "1"], ["**electron**", "moving round the nucleus in shells", "negative (−1)", "about 1/1840 – tiny"]],
      then=["A neutral atom has **equal numbers of protons and electrons**, so the charges cancel."]),
    I("Predict, watch, explain: a balloon and a stream of water",
      "A balloon is rubbed on dry hair, then held near a thin stream of tap water without touching it. The stream **bends towards** the balloon.",
      then=["Rubbing moved **electrons** from the hair onto the balloon, giving it a **negative** charge. Opposite charges attract, so the water is pulled towards it.",
            "The same kind of force holds electrons in an atom."]),
    I("What holds electrons in the atom?",
      "Like charges **repel**; opposite charges **attract**. The positive protons in the nucleus attract the negative electrons – this is the **electrostatic force**. It stops the electrons flying away.",
      then=["A different, very strong force (the nuclear force) holds the protons and neutrons together in the nucleus."]),
    I("Atomic number and electron shells",
      "The **atomic number** is the number of **protons**. It decides which element an atom is, and in a neutral atom it also equals the number of **electrons**.",
      table=[["Element", "Symbol", "Atomic number", "Electrons in shells"],
             ["hydrogen", "H", "1", "1"], ["helium", "He", "2", "2"], ["carbon", "C", "6", "2, 4"], ["nitrogen", "N", "7", "2, 5"], ["oxygen", "O", "8", "2, 6"],
             ["sodium", "Na", "11", "2, 8, 1"], ["chlorine", "Cl", "17", "2, 8, 7"]],
      then=["Electrons fill **shells**: the first holds up to **2**, the second up to **8**, the third up to 8 (at this level)."]),
    W("Arranging electrons",
      "Aluminium has atomic number 13. Write its electron arrangement.",
      [("13 protons, so 13 electrons", "the atom is neutral"), ("first shell: 2", "full at 2"), ("second shell: 8", "full at 8"), ("third shell: 13 − 10 = 3", "the rest")], "2, 8, 3"),
    Y("Electrons in shells",
      mcq("s8u04r11", "Magnesium has atomic number 12. What is its electron arrangement?",
          [("2, 8, 2", True, "Yes – 2 + 8 + 2 = 12."), ("2, 10", False, "The second shell holds only 8."), ("8, 4", False, "The first shell holds only 2."), ("2, 2, 8", False, "Fill the inner shells first.")],
          "Fill the first shell (2), then the second (8).", "12 electrons: 2, 8, 2.")),
    I("Full outer shells",
      "Atoms are most **stable** with a **full outer shell**. Atoms can share or lose electrons to get one.",
      then=["Two hydrogen atoms **share** their electrons to make a hydrogen molecule, H₂; two nitrogen atoms share to make N₂. Carbon has 4 outer electrons and shares them with up to 4 other atoms – that is why carbon is the backbone of living things.",
            "Atoms of the same element can have different numbers of neutrons: these are **isotopes** (carbon-12 has 6 neutrons; carbon-14 has 8)."]),
    K("Key points",
      "Atoms contain **protons** (+, in nucleus), **neutrons** (0, in nucleus) and **electrons** (−, in shells).",
      "Neutral atom: protons = electrons. **Atomic number** = number of protons.",
      "The **electrostatic force** between the + nucleus and − electrons holds the atom together.",
      "Shells hold 2, then 8, then 8 electrons; atoms share or lose electrons to get full outer shells."),
    book=BK(
        [("proton", "a positive particle in the nucleus"), ("neutron", "a particle with no charge in the nucleus"), ("electron", "a tiny negative particle in a shell round the nucleus"),
         ("nucleus", "the tiny centre of an atom"), ("atomic number", "the number of protons in an atom"), ("electrostatic force", "the force between charged particles"),
         ("isotopes", "atoms of the same element with different numbers of neutrons")],
        [], [],
        [Ex("Copy and complete for proton, neutron, electron: charge and position.", ans="proton +, nucleus; neutron 0, nucleus; electron −, shells round the nucleus"),
         Ex("Write the electron arrangement for: (a) oxygen (8) (b) neon (10) (c) phosphorus (15).", ans="(a) 2, 6 (b) 2, 8 (c) 2, 8, 5"),
         Ex("An atom has 9 protons. How many electrons does it have? Which element is it?", ans="9 electrons; fluorine"),
         Ex("Why is an atom neutral overall?", ans="It has equal numbers of positive protons and negative electrons."),
         Ex("Explain, using charges, why a rubbed balloon sticks to a wall.", ans="The balloon gains electrons (negative); it attracts the positive charges in the wall's surface – opposite charges attract.", think=True)],
        ["describe the particles in an atom and their charges", "explain what holds electrons in an atom", "use atomic number", "arrange electrons in shells"],
        look=["the particle table", "the electron arrangements"],
        note="Read it after the video: protons, neutrons, electrons, atomic number and shells (answers at the back)."),
)

# =====================================================================================================
# 4.2 Development of the atomic model · 8Cm.01, 8SIC.01, 8TWSp.02
# =====================================================================================================
READ["4.2"] = L(
    H("Seeing the invisible",
      "Nobody can see inside an atom with an ordinary microscope. Yet we know there is a tiny nucleus at its centre.",
      "How could scientists find out what is inside something they cannot see?"),
    I("How the atomic model developed",
      "Scientists built **models** of the atom and changed them when new evidence appeared.",
      table=[["Year", "Scientist", "Model or discovery"],
             ["1803", "John Dalton", "atoms are tiny solid balls, a different kind for each element"],
             ["1904", "J. J. Thomson", "discovered electrons; '**plum pudding**' model: negative electrons in a ball of positive charge"],
             ["1911", "Ernest Rutherford", "**nuclear model**: a tiny, dense, positive nucleus with electrons around it"],
             ["1913", "Niels Bohr", "electrons move in fixed **shells** (energy levels)"],
             ["1926", "Erwin Schrödinger", "electrons described as a 'cloud' around the nucleus"],
             ["1932", "James Chadwick", "discovered the **neutron** in the nucleus"]],
      then=["Each scientist built on the work of those before – a model is kept only while it explains the evidence."]),
    I("Predict, watch, explain: the gold foil experiment",
      "Rutherford's team fired positive **alpha particles** at gold foil only a few hundred atoms thick. If the plum pudding model were right, the thin spread of positive charge should let every particle pass almost straight through.",
      fig={"kind": "sciGoldFoil"},
      table=[["Observation", "What it shows"], ["most alpha particles went straight through", "the atom is mostly **empty space**"],
             ["a few were deflected at large angles", "there is a concentrated **positive** charge that repels them"],
             ["a very few bounced straight back", "the positive charge and most of the mass are packed into a **tiny, dense nucleus**"]],
      then=["The plum pudding model could not explain the particles bouncing back, so it was replaced by the **nuclear model**."]),
    Y("What did it show?",
      mcq("s8u04r21", "Most alpha particles passed straight through the gold foil. What did this show?",
          [("Atoms are mostly empty space.", True, "Yes."), ("Atoms have no nucleus.", False, "The bounced-back particles showed there is a nucleus."),
           ("Gold atoms are negatively charged.", False, "Atoms are neutral."), ("Electrons are heavy.", False, "Electrons are very light.")],
          "Most passed straight through – what were they passing through?", "Passing through without hitting anything means mostly empty space.")),
    Y("Order the models",
      mcq("s8u04r22", "Which list puts the models in the order they were proposed?",
          [("solid ball → plum pudding → nuclear → shells", True, "Yes: Dalton, Thomson, Rutherford, Bohr."), ("plum pudding → solid ball → shells → nuclear", False, "Dalton's solid ball came first."),
           ("nuclear → plum pudding → solid ball → shells", False, "The nuclear model replaced the plum pudding."), ("shells → nuclear → solid ball → plum pudding", False, "Shells came last of these.")],
          "Use the table of dates.", "Dalton 1803, Thomson 1904, Rutherford 1911, Bohr 1913.")),
    K("Key points",
      "Models of the atom: Dalton (solid balls) → Thomson (plum pudding) → Rutherford (nuclear) → Bohr (shells) → Schrödinger (electron cloud); Chadwick found the neutron.",
      "Gold foil experiment: most particles pass through (empty space); a few bounce back (tiny dense positive nucleus).",
      "Scientific models change when new evidence cannot be explained."),
    book=BK(
        [("model", "a simplified picture that explains how something works"), ("plum pudding model", "electrons scattered in a ball of positive charge"),
         ("nuclear model", "a tiny dense positive nucleus with electrons around it"), ("alpha particle", "a small, fast, positively charged particle")],
        [], [],
        [Ex("Describe the plum pudding model.", ans="A ball of positive charge with negative electrons scattered through it."),
         Ex("Give the three observations of the gold foil experiment and what each shows.", ans="most pass through – mostly empty space; some deflected – positive charge concentrated; a few bounce back – tiny, dense, positive nucleus"),
         Ex("What did Bohr add to Rutherford's model?", ans="Electrons move in fixed shells (energy levels)."),
         Ex("Quick quiz.", ("Name the three particles in an atom and their charges.", "proton +, neutron 0, electron −"), ("Oxygen's atomic number is 8. How many electrons?", "8 (2, 6)"),
            ("Which force holds electrons in an atom?", "the electrostatic force"), ("What did the gold foil experiment show?", "a tiny, dense, positive nucleus; atoms mostly empty space")),
         Ex("Explain why scientists replaced the plum pudding model instead of keeping it.", ans="It could not explain why some alpha particles bounced back; the nuclear model could.", think=True)],
        ["describe how the model of the atom developed", "explain the gold foil experiment and what it showed"],
        look=["the timeline of models", "the gold foil results"],
        note="Read it after the video: the development of the atomic model and the gold foil experiment, plus a quick quiz (answers at the back)."),
)
